import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"🔬 科学日报 | 2026年7月23日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-07-23.md","filePath":"science-log/src/science-daily/2026-07-23.md"}'),e={name:"science-log/src/science-daily/2026-07-23.md"};function g(a,o,i,c,p,u){return n(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年7月23日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年7月23日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年7月23日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年7月23日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：2026-07-23 重建版简讯（事后回溯重建，共 10 条：科学 5 + AI 5） 分析日期：2026-07-23 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-07 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-台阶几何「引导」层间滑移-纯相菱方石墨烯长到-160×80-微米" tabindex="-1">1. 台阶几何「引导」层间滑移：纯相菱方石墨烯长到 160×80 微米 <a class="header-anchor" href="#_1-台阶几何「引导」层间滑移-纯相菱方石墨烯长到-160×80-微米" aria-label="Permalink to &quot;1. 台阶几何「引导」层间滑移：纯相菱方石墨烯长到 160×80 微米&quot;">​</a></h3><p><strong>原文</strong>：菱方（ABC）堆叠石墨烯是研究关联与拓扑物理的明星平台，但它热力学上亚稳、动力学上不稳，规模化制备纯相一直是死结。</p><p><strong>深度扩展</strong>：</p><p>该工作发表于《Science》（2026-07-23），由北京大学/中科院物理所刘开辉、陆晓博、刘中恺与冯济、王恩哥等合作完成（Mengze Zhao、Zhibin Zhang、Xin Sui、Quanlin Guo、Cheng Qian、Sheng Wang、Li Wang、Xin-Zheng Li 等 19 位作者）。菱方石墨烯的难点是<strong>结构本身的亚稳性</strong>：ABC 堆叠在自由能上不是全局最优，层与层之间只要发生一次剪切滑移，就会退化为更稳定的 AB 或孪晶堆叠，所以此前只能在机械解理的极小块上碰运气找到。</p><p>团队的办法不是&quot;更快地长&quot;，而是<strong>用衬底台阶把滑移方向固定住</strong>：台阶的边缘与高度构成一个几何模板，外延生长时每一层都在同一侧成核、沿同一方向推进，层间滑移量因此被确定性地锁定在同一符号上，堆叠序列自动对齐到 ABC。结果相纯度 <strong>&gt;99%</strong>，单晶区面积 <strong>160 μm × 80 μm</strong>、厚度覆盖约 15 层到 120 nm——这个尺度比此前报道的菱方石墨烯大出若干量级。</p><p>他们还补上了此前最缺的一块基础设施：从少层膜一直到约 200 层的体材料，给出<strong>完整的拉曼指纹参考集与内禀能带数据</strong>。这意味着以后别人拿到一片样品，用拉曼就能判定堆叠序，不必每篇论文各自标定。输运测量直接观测到<strong>层间反铁磁态</strong>与<strong>量子反常霍尔效应</strong>，说明这类&quot;只在几微米样品上出现过&quot;的关联拓扑物态，现在有了可批量制造的材料底座。</p><p>对领域的意义是双重的：一是把&quot;堆叠序&quot;从一个难以控制的偶然变量变成可设计的工艺参数；二是给出了一个方法论范式——<strong>用衬底的几何约束替代对热力学稳定性的依赖</strong>，这对其他亚稳范德华相（如菱方 BN、亚稳过渡金属硫族化合物堆垛）同样可移植。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code> 中二维材料堆叠工程条目同源；量子反常霍尔部分见 <code>topics/quantum-physics/index.md</code>。</p><hr><h3 id="_2-18-年光谱里找出行星周期-gj-436-b-的磁场被夹到-6–110-高斯" tabindex="-1">2. 18 年光谱里找出行星周期：GJ 436 b 的磁场被夹到 6–110 高斯 <a class="header-anchor" href="#_2-18-年光谱里找出行星周期-gj-436-b-的磁场被夹到-6–110-高斯" aria-label="Permalink to &quot;2. 18 年光谱里找出行星周期：GJ 436 b 的磁场被夹到 6–110 高斯&quot;">​</a></h3><p><strong>原文</strong>：理论早有预言：一颗磁场足够强的行星若近距离绕转，会与宿主星产生星—行星磁相互作用，表现为与行星轨道周期同步的光学或射电活动信号；但这条预言此前从未被&quot;读数&quot;成功。</p><p><strong>深度扩展</strong>：</p><p>这是《Science》（2026-07-23）的一项长基线观测成果，作者为 D. Revilla、P. J. Amado、R. Luque、P. Schöfer、A. F. Lanza、A. Binnenfeld、J. A. Caballero、A. P. Hatzes、S. V. Jeffers、I. Ribas、S. Zucker 等（CARMENES 联盟，主力单位包括西班牙安达卢西亚天体物理研究所 IAA-CSIC、德国海德堡州立天文台、以色列特拉维夫大学等）。</p><p>测量对象是 <strong>GJ 436</strong>：一颗 M 型矮星，被一颗海王星大小的行星 GJ 436 b 以<strong>极轨、偏心</strong>轨道近距离绕转。研究用的是 <strong>18 年</strong>的高分辨率光学光谱——这个时长本身是关键，因为恒星自身的活动周期（自转、磁活动周）会伪装成行星信号，只有基线长到能同时分辨&quot;行星轨道周期&quot;与&quot;恒星自转周期&quot;两个时间尺度，才可能把二者分开。</p><p>分析结果显示：多个恒星活动指标在<strong>行星轨道周期</strong>上出现增强，其幅度又被<strong>恒星自转</strong>调制，并叠加在恒星 <strong>8 年磁活动周</strong>的包络上。这种&quot;三重周期性同时对齐&quot;很难用纯恒星活动解释。团队用几何模型做反演，只有当 GJ 436 b 的磁场强度落在 <strong>6–110 高斯</strong>这个区间时，才能同时复现上述周期结构。</p><p>为什么数值区间这么宽？因为信号只提供&quot;相互作用的强度投影&quot;，磁场强度与磁层尺度、轨道倾角存在退化。但即便如此，6 高斯的下限已经意味着 GJ 436 b 拥有<strong>相当强的内禀磁场</strong>（地球约 0.25–0.65 高斯，木星约 4–14 高斯），上限则把它推到接近木星量级。</p><p>科学价值在于打开了一条<strong>系外行星磁场的间接测量通道</strong>。行星磁场是判断行星内部是否存在发电机过程、能否抵御恒星风剥蚀大气、进而能否维持宜居性的核心参数，但在此之前，除太阳系外没有任何一颗系外行星有磁场强度估计。这项工作把&quot;磁场&quot;从模型假设变成了可观测约束。</p><p><strong>跨主题关联</strong>：恒星活动—行星相互作用与 <code>topics/physics/index.md</code> 中的等离子体/磁流体条目可互参；观测方法论与库内 <code>topics/space-energy/index.md</code> 的空间探测记录同构。</p><hr><h3 id="_3-海马体衰老的四维重编程-小胶质细胞「换血」、星形胶质细胞退场、3d-基因组全面侵蚀" tabindex="-1">3. 海马体衰老的四维重编程：小胶质细胞「换血」、星形胶质细胞退场、3D 基因组全面侵蚀 <a class="header-anchor" href="#_3-海马体衰老的四维重编程-小胶质细胞「换血」、星形胶质细胞退场、3d-基因组全面侵蚀" aria-label="Permalink to &quot;3. 海马体衰老的四维重编程：小胶质细胞「换血」、星形胶质细胞退场、3D 基因组全面侵蚀&quot;">​</a></h3><p><strong>原文</strong>：基因表达在人脑衰老中会变，但调控层到底改了什么长期不清楚。</p><p><strong>深度扩展</strong>：</p><p>《Science》（2026-07-23）。第一作者 Nathan R. Zemke、Seoyeon Lee、Sainath Mamde，通讯层含 Nicole Berchtold、Bing Yang、Ting Wang（华盛顿大学）与 Jingtian Zhou 等，是一项跨机构的人脑衰老多组学工程。数据规模的核心不是人数，而是<strong>每个人被同时测了四层信息</strong>：单核 RNA 表达、单核染色质可及性（ATAC）、DNA 甲基化，以及<strong>三维染色质构象</strong>（Hi-C 类测量）。样本覆盖人类海马体从成年早期到老年的完整跨度。</p><p>四条主要发现可以排成一条因果链：</p><p>其一，调控程序既有<strong>线性漂移</strong>，也有<strong>非线性跳变</strong>——转录因子活性并不是匀速下降，而是在某些年龄段成阶梯式改变。其二，<strong>50–75 岁之间小胶质细胞发生了&quot;换血&quot;</strong>：胚胎卵黄囊来源的常驻小胶质细胞被耗竭，取而代之的是转录上类似<strong>外周血单核细胞来源</strong>的细胞。这解释了为什么老年人脑内炎症基调偏高——新迁入的细胞带有更强的外周免疫记忆。其三，<strong>海马星形胶质细胞随年龄显著减少</strong>，且减少的包括专门调控突触传递的那一亚群，直接对应海马可塑性与记忆编码能力的下降。其四，跨越所有细胞类型，<strong>三维基因组架构全局性&quot;侵蚀&quot;</strong>——拓扑关联结构域边界变弱、长程环化减少。</p><p>这四层的关系是关键：3D 基因组侵蚀不是伴随现象，而是<strong>上游约束的松动</strong>。染色质环是把增强子与启动子拉到一起的物理装置，装置松了，调控程序就必然出现非线性失衡；而细胞组成替换（小胶质换血、星形胶质退场）则是在松动的地基上叠加的第二重变化。论文的落点是&quot;细胞类型特异的衰老干预靶点&quot;，但它真正提供的是一个<strong>分层的因果顺序</strong>：先有空间基因组解体，再有调控失序，最后表现为细胞类型比例改写。</p><p><strong>跨主题关联</strong>：与 <code>topics/neuroscience/index.md</code> 的神经退行与胶质细胞条目直接对接；细胞替换—表观遗传视角见 <code>topics/biomedicine/index.md</code>。</p><hr><h3 id="_4-绳文与弥生两副高覆盖基因组-冰期后人口轨迹彻底分岔-amy1-拷贝数在稻作之前就已增高" tabindex="-1">4. 绳文与弥生两副高覆盖基因组：冰期后人口轨迹彻底分岔，AMY1 拷贝数在稻作之前就已增高 <a class="header-anchor" href="#_4-绳文与弥生两副高覆盖基因组-冰期后人口轨迹彻底分岔-amy1-拷贝数在稻作之前就已增高" aria-label="Permalink to &quot;4. 绳文与弥生两副高覆盖基因组：冰期后人口轨迹彻底分岔，AMY1 拷贝数在稻作之前就已增高&quot;">​</a></h3><p><strong>原文</strong>：日本本土古 DNA 保存差，此前几乎没有高分辨率基因组。</p><p><strong>深度扩展</strong>：</p><p>《PNAS》（2026-07-23），作者为 Koji Ishiya、Fuzuki Mizuno、Jun Gojobori、Masahiko Kumagai、Yasuhiro Taniguchi、Osamu Kondo、Masami Matsushita、Takayuki Matsushita、Li Wang、Kunihiko Kurosaki、Shintaroh Ueda（日本多所高校与博物馆联合，含东京大学、北里大学、国立科学博物馆等）。</p><p>技术难度先要说清：日本列岛高温高湿，古 DNA 降解严重且现代污染难除，所以此前本土样本多为线粒体或低覆盖核基因组。这次团队拿到两例<strong>低污染、高覆盖</strong>核基因组：一例<strong>绳文早期个体 &gt;67×</strong>、一例<strong>弥生中期个体 &gt;46×</strong>。67× 覆盖意味着几乎所有位点都能做可靠二倍体分型，可以逐个体推断近交、有效群体大小与祖源成分，而不是只能做群体平均。</p><p>结论分层很清楚：</p><ul><li><strong>共同点</strong>：两条谱系在**末次盛冰期（LGM）**都经历了有效群体收缩——列岛在此期间与大陆的连接状况恶劣，人口瓶颈是共同的。</li><li><strong>分岔点</strong>：冰期之后完全相反。绳文谱系是<strong>长期稳定、几乎无可辨识的扩张</strong>；弥生相关祖先群体则<strong>持续缓慢增长</strong>。这推翻了&quot;绳文人口在冰期后也回升&quot;的默认假设。</li><li><strong>连续性</strong>：弥生中期个体与<strong>今日本土日本人</strong>之间存在明确遗传连续性，这为现代日本人群&quot;绳文 + 弥生 + 古坟&quot;三层祖源模型中的中间层提供了锚点。</li><li><strong>反转点</strong>：绳文早期个体携带<strong>更高的唾液淀粉酶 AMY1 拷贝数</strong>。AMY1 拷贝数与富淀粉饮食的适应长期被绑定在&quot;农业扩散之后&quot;的叙事里，而这里它出现在<strong>稻作大规模扩张之前</strong>的狩猎采集—渔猎背景中。合理推测是：以块茎、坚果、贝类等高淀粉/糖原食物为生的采集经济，同样构成对 AMY1 的选择压力。</li></ul><p>方法学意义：它证明了在 DNA 保存恶劣的地区，<strong>靠少数超高覆盖个体</strong>也能做个体级人口史推断，而不必依赖大样本低覆盖的统计近似。</p><p><strong>跨主题关联</strong>：与 <code>topics/paleoanthropology/index.md</code> 的古基因组条目及库内&quot;农业—基因共演化&quot;讨论同构；饮食适应的表型层面见 <code>topics/fitness/index.md</code>。</p><hr><h3 id="_5-活性—抗性权衡-复活七百万年前的酶-看到抗药性每次都以催化效率为代价" tabindex="-1">5. 活性—抗性权衡：复活七百万年前的酶，看到抗药性每次都以催化效率为代价 <a class="header-anchor" href="#_5-活性—抗性权衡-复活七百万年前的酶-看到抗药性每次都以催化效率为代价" aria-label="Permalink to &quot;5. 活性—抗性权衡：复活七百万年前的酶，看到抗药性每次都以催化效率为代价&quot;">​</a></h3><p><strong>原文</strong>：抗生素产生菌身上的&quot;自抗性基因&quot;是个悖论：抗性怎么可能在抗生素出现之前就进化出来？</p><p><strong>深度扩展</strong>：</p><p>《PNAS》（2026-07-23）。作者 Alexander W. Sarkis、Jens Laurids Sørensen、Teis Esben Sondergaard、Kåre Lehmann Nielsen、Jens C. Frisvad、Douglas L. Theobald、Lizbeth Hedstrom（布兰迪斯大学、丹麦奥尔堡大学、丹麦技术大学合作）。</p><p>模型系统选得极巧：<strong>霉酚酸（MPA）<strong>抑制</strong>次黄嘌呤单核苷酸脱氢酶（IMPDH）</strong>，而产 MPA 的真菌基因组里，MPA 生物合成基因簇<strong>自带一个抗性版 IMPDH-B</strong>。这就构成了那个悖论——抗性基因为什么先于抗生素存在？</p><p>演化史证据先摆出来：IMPDH-B 的同源物广泛存在于<strong>不产 MPA 的真菌</strong>中，且这些基因组里还能检测到 MPA 基因簇的残留碎片；IMPDH-B 的系统树与真菌<strong>物种树不一致</strong>，指向 Aspergillus 与 Sordariomycetes 之间<strong>多次水平基因转移</strong>。也就是说，抗性酶在真菌世界里早已流通，MPA 生物合成的出现是后来事件。</p><p>然后是实验的核心：团队表征 <strong>11 个现存 IMPDH-B</strong>（5 个来自产生菌、6 个来自非产生菌），并<strong>复活了 7 个祖先酶（Anc1–Anc7）</strong>。结果是教科书级别的清晰——<strong>MPA 抗性出现在 Anc2 与 Anc3 之间，且恰好伴随催化效率的下降</strong>；在祖先与现存酶的全部样本中，&quot;抗性越强&quot;与&quot;活性越低&quot;始终强相关。这条权衡不是当代耐药性才有的现象，它已经持续了<strong>数百万年</strong>。</p><p>意外发现有两层：其一，IMPDH-B 与祖先酶 Anc3–Anc7 <strong>同时对利巴韦林单磷酸（RVP）<strong>抗性，而 MPA 与 RVP 结合的是</strong>相近的酶构象</strong>——所以这条权衡很可能不是&quot;专门为 MPA 付出的代价&quot;，而是&quot;必须同时抗多种相似抑制剂&quot;这一设计约束的必然结果。其二，Anc1 与 Anc2 对 MPA 同样敏感，但 Anc2 已降低对 RVP 的敏感性——暗示<strong>先有的另一种抗性为 MPA 生物合成铺好了许可性背景</strong>：先解决&quot;我能容忍这类分子&quot;，再谈&quot;我要自己造它&quot;。</p><p>这给抗生素耐药性研究提供了一个反向视角：耐药突变的代价不是偶然的，而是由<strong>抑制剂结合的构象空间</strong>结构性地决定的；如果两种药物的结合构象差异足够大，权衡就可能被解耦。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的抗微生物耐药条目同构；蛋白构象—功能权衡的一般讨论见 <code>topics/physics/index.md</code>（统计力学视角）与 <code>topics/cross-domain-synthesis-2026-q3.md</code>。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-leact-从专家的「沉默动作」里反推思维链" tabindex="-1">6. LeAct：从专家的「沉默动作」里反推思维链 <a class="header-anchor" href="#_6-leact-从专家的「沉默动作」里反推思维链" aria-label="Permalink to &quot;6. LeAct：从专家的「沉默动作」里反推思维链&quot;">​</a></h3><p><strong>原文</strong>：推理模型吃的是推理数据，来源无非人工标注或从更强模型蒸馏；但真正的推理富矿其实是专家系统。</p><p><strong>深度扩展</strong>：</p><p>arXiv（2026-07-23），作者 Ziran Yang、Chengshuai Shi、Raj Ghugare、Benjamin Eysenbach、Karthik Narasimhan、Chi Jin（普林斯顿大学，合作者含 Eysenbach 与 Narasimhan，两人分别在自监督世界模型与语言智能体方向有长期工作）。</p><p>问题设定很清楚：游戏引擎、经典规划器、定理证明器这类专家系统能在广泛任务上产出<strong>近最优动作</strong>，但它们是&quot;沉默的&quot;——只给动作，不给理由。人类标注与 LLM 蒸馏能提供 CoT，但前者贵、后者受制于更强的模型本身。于是核心问题变成：<strong>能否只从动作反推推理？</strong></p><p>LeAct 的做法是把 CoT 建模成<strong>潜变量</strong>并做&quot;可验证筛选&quot;：学生针对每个专家动作采样若干候选 CoT，然后只保留那些<strong>实测能提高学生自己复现该动作概率</strong>的候选，用这个筛选信号去优化潜变量。训练里没有任何自然语言监督，唯一的裁判是&quot;按这条推理走，你是否更可能做出专家那个动作&quot;。</p><p>结果在三个维度上都很硬：在小规模可枚举博弈上，它触到了<strong>求解器的数值下限</strong>（理论上不可能更好）；在更大规模上，它与求解器的距离比最强的 expert-iteration 基线<strong>近 5 倍</strong>；在约 <strong>10⁹ 个信息集</strong>的 Flop Hold&#39;em 上，头对头胜出 <strong>+60 mbb/g</strong>；在模拟机器人探针上，它是<strong>唯一一个</strong>优于直接模仿（behavior cloning）的训练配方。</p><p>为什么重要：这是把&quot;推理监督的来源&quot;从<strong>人类与更强模型</strong>扩展到<strong>任何可查询的专家系统</strong>。理论上这意味着，形式化验证器、编译器优化器、棋类引擎、调度求解器都可以成为推理教师——它们的共同特征是动作可验证、理由不可见，而 LeAct 恰好只需要前者。风险也很明确：当专家动作本身在分布外、或存在多个同样正确的动作时，&quot;复现概率&quot;这个奖励会偏向模式化的推理而非真正的因果链，这在该方法从博弈推广到开放域时会是主要摩擦点。</p><p><strong>跨主题关联</strong>：与 <code>topics/intelligence-self-learning/index.md</code> 的自我改进/自蒸馏条目直接对接；与 <code>topics/ai-brain/index.md</code> 中&quot;可验证性作为学习信号&quot;的讨论同构。</p><hr>',64)])])}const l=t(e,[["render",g]]);export{h as __pageData,l as default};
